package com.fraymus.omega;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Objects;
import java.util.concurrent.TimeUnit;

/**
 * LeanProofBridge executes Lean 4 as an external verifier for safety proofs generated by the Amygdala.
 * The bridge writes the supplied Lean script into a temporary file, invokes the Lean executable, and
 * inspects the resulting output to determine whether the proof (and therefore the action) is allowed.
 *
 * The bridge expects the script to define a Boolean value named {@code policyAllows}. After the script
 * is evaluated, the bridge appends a small footer that prints "ALLOW" when the policy permits execution
 * and "BLOCK" otherwise. Any non-zero exit code or missing "ALLOW" marker is treated as a verification
 * failure.
 */
public class LeanProofBridge {

    private static final String DEFAULT_EXECUTABLE = System.getenv().getOrDefault("LEAN4_PATH", "lean");
    private static final Duration DEFAULT_TIMEOUT = Duration.ofSeconds(10);
    private static final String SCRIPT_PREAMBLE = "import Std\nopen Classical\n";
    private static final String SCRIPT_EPILOGUE = "#eval if policyAllows then \"ALLOW\" else \"BLOCK\"\n";

    private final String executable;
    private final Duration timeout;

    public LeanProofBridge() {
        this(DEFAULT_EXECUTABLE, DEFAULT_TIMEOUT);
    }

    public LeanProofBridge(String executable, Duration timeout) {
        this.executable = Objects.requireNonNullElse(executable, DEFAULT_EXECUTABLE);
        this.timeout = timeout == null || timeout.isNegative() || timeout.isZero() ? DEFAULT_TIMEOUT : timeout;
    }

    /**
     * Verifies the supplied Lean script. The returned {@link ProofResult} contains the outcome, any emitted
     * diagnostics, and the underlying exit code. If Lean cannot be invoked, the result is marked as a failure
     * with a descriptive message so that the caller can fail safely.
     */
    public ProofResult verify(String scriptBody) {
        if (scriptBody == null || scriptBody.isBlank()) {
            return ProofResult.failure("Empty Lean script");
        }

        Path tempFile = null;
        try {
            tempFile = Files.createTempFile("fraynix-proof-", ".lean");
            String fullScript = SCRIPT_PREAMBLE + scriptBody + System.lineSeparator() + SCRIPT_EPILOGUE;
            Files.writeString(tempFile, fullScript, StandardCharsets.UTF_8);

            ProcessBuilder pb = new ProcessBuilder(executable, tempFile.toAbsolutePath().toString());
            pb.redirectErrorStream(true);
            Process process = pb.start();

            StreamCollector collector = new StreamCollector(process.getInputStream());
            collector.start();

            boolean finished = process.waitFor(timeout.toMillis(), TimeUnit.MILLISECONDS);
            if (!finished) {
                process.destroyForcibly();
                return ProofResult.failure("Lean verification timed out after " + timeout.toSeconds() + " seconds");
            }

            collector.join();
            String output = collector.output();
            int exitCode = process.exitValue();
            boolean success = exitCode == 0 && output.contains("ALLOW");

            if (!success) {
                String reason = "Lean verification failed (exit=" + exitCode + ")";
                return ProofResult.failure(reason, output, exitCode);
            }

            return ProofResult.success(output, exitCode);
        } catch (IOException e) {
            return ProofResult.failure("Unable to invoke Lean executable: " + e.getMessage());
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            return ProofResult.failure("Lean verification interrupted: " + ie.getMessage());
        } finally {
            if (tempFile != null) {
                try {
                    Files.deleteIfExists(tempFile);
                } catch (IOException ignored) {
                    // Best-effort cleanup.
                }
            }
        }
    }

    private static final class StreamCollector extends Thread {
        private final InputStream stream;
        private final StringBuilder buffer = new StringBuilder();

        private StreamCollector(InputStream stream) {
            this.stream = stream;
            setDaemon(true);
            setName("lean-proof-stream");
        }

        @Override
        public void run() {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    buffer.append(line).append(System.lineSeparator());
                }
            } catch (IOException ignored) {
                // Stream collection best-effort.
            }
        }

        String output() {
            return buffer.toString();
        }
    }

    /**
     * Immutable verification result from Lean. When {@code success} is {@code false}, callers should treat the
     * associated action as blocked and present the diagnostic information to operators.
     */
    public static final class ProofResult {
        private final boolean success;
        private final String message;
        private final String output;
        private final int exitCode;

        private ProofResult(boolean success, String message, String output, int exitCode) {
            this.success = success;
            this.message = message;
            this.output = output;
            this.exitCode = exitCode;
        }

        public static ProofResult success(String output, int exitCode) {
            return new ProofResult(true, "ALLOW", output, exitCode);
        }

        public static ProofResult failure(String message) {
            return new ProofResult(false, message, "", -1);
        }

        public static ProofResult failure(String message, String output, int exitCode) {
            return new ProofResult(false, message, output == null ? "" : output, exitCode);
        }

        public boolean success() {
            return success;
        }

        public String message() {
            return message;
        }

        public String output() {
            return output;
        }

        public int exitCode() {
            return exitCode;
        }
    }
}
